-- Rifts World Book 36: Sovietski: 34 special rounds, grenades, attachments, rifles and unusual weapons, printed 217-223.
-- 34 gear rows.
--
-- One-off data script, run once per environment. NOT a migration - it adds
-- rows, not schema.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~380-sovietski-weapons.sql
--
-- Written by scripts/rows-sql.mjs from 1 worker file(s). Every value is
-- printable ASCII and every row cites its book. Rows are keyed on their
-- portable identity, never an id; a row already held is left as it is.
--
-- Printed pp.217-223 (cache p213-p219): 5 special shotgun and rail gun rounds,
-- 8 grenades and 2 flares, 8 weapon attachments, 8 rifles and 8 unusual
-- weapons, 39 items. 34 rows here; 5 are left out because a held row already
-- carries the same figures: Plasma Grenade (triax-plasma-grenade), Stun/Flash
-- Grenade (stun-flash-grenade), Tear Gas Grenade (triax-tear-gas-grenade),
-- Smoke Grenade (smoke-grenade) and Handheld Flare (triax-handheld-flare).
-- Every damage, range and payload figure was read off a 150 dpi render, not the
-- text layer. Where a held row of the same name prints different figures
-- (Fragmentation Grenade, Parachute Flare, Vibro-Bayonet, Dragunov SVD,
-- Silencer, Flash Suppressor), this book's item is its own row and the held
-- row is left alone.

INSERT OR IGNORE INTO gear (slug, name, system, category, weight_lbs, cost, cost_note, damage, is_mega_damage, range, payload, rate_of_fire, ar, sdc, mdc, description, source_book, vehicle_slug) VALUES
  ('sovietski-high-explosive-shotgun-round', 'High Explosive (HE) Shotgun and Rail Gun Round', 'rifts', 'weapon', NULL, NULL, NULL, '1D6 M.D.', 1, 'As per the weapon firing it', NULL, NULL, NULL, NULL, NULL, 'Special Sovietski ammunition: a shotgun shell or rail gun round packed with high explosive so that an ordinary projectile weapon can do Mega-Damage. Meant for use against armor. The book prints no price.', 'Rifts World Book 36: Sovietski p.217', NULL),
  ('sovietski-paint-rounds', 'Paint Rounds', 'rifts', 'weapon', NULL, 2, '2 credits each', '1 S.D.C. per shotgun round; 1D6 S.D.C. per rail gun burst', 0, 'As per the weapon firing it', NULL, NULL, NULL, NULL, NULL, 'Marking rounds for training, war games and tagging targets, made for projectile weapons of every caliber. A hit leaves a splash of paint about as big as a golf ball and usually just stings. Firing them is -1 to strike.', 'Rifts World Book 36: Sovietski p.217', NULL),
  ('sovietski-solid-slug-metal', 'Solid Slug: Metal', 'rifts', 'weapon', NULL, 2, '2 credits per slug', '6D6 S.D.C. as a rail gun round or shotgun slug; 2D6 S.D.C. to all in a 2 foot (0.6 m) radius as shotgun scatter shot; double damage to creatures vulnerable to the metal', 0, 'As per the weapon firing it', NULL, NULL, NULL, NULL, NULL, 'A plain solid projectile for shotguns and some rail guns, of iron, steel, lead or a composite, all doing the same damage. It serves against soft targets and against monsters that a particular metal hurts. The silver and wood slugs are the specialised versions.', 'Rifts World Book 36: Sovietski p.217', NULL),
  ('sovietski-solid-slug-silver', 'Solid Slug: Silver', 'rifts', 'weapon', NULL, 100, '100 credits per round', 'Shotgun or rail gun: 6D6 S.D.C. per slug, or 2D6 S.D.C. to all in a 2 foot (0.6 m) radius as scatter shot. Handguns: as per caliber, typically 3D6, 4D6 or 5D6 S.D.C.; S.D.C. rifles 6D6, 7D6 or 1D4x10 S.D.C. Double damage to creatures vulnerable to silver', 0, 'As per the weapon firing it', NULL, NULL, NULL, NULL, NULL, 'Silver ammunition for use against werewolves, vampires and many demons and other supernatural beings. Silver bullets for handguns and rifles are common enough; the Sovietski also makes heavy silver slugs for shotguns and rail guns, which feeds talk that it mines silver on some other world reached through a Rift or by magic.', 'Rifts World Book 36: Sovietski p.217', NULL),
  ('sovietski-solid-slug-wood', 'Solid Slug: Wood, Bone or Stone', 'rifts', 'weapon', NULL, 5, '5 credits per round', '2D6+2 S.D.C.; double, often counted as M.D., to creatures vulnerable to wood (or stone). A shattered round does 1D4 S.D.C. to all within 4 feet (1.2 m) of the target', 0, 'As per the weapon firing it', NULL, NULL, NULL, NULL, NULL, 'A big bullet of juniper or birch on a metal base (bone and stone versions exist too) for monsters and demons that wood or stone can harm. Fired from a rail gun it has a 01-15% chance of breaking apart into a nearly harmless spray of splinters. Of little use against M.D.C. machines and armor. -1 to strike.', 'Rifts World Book 36: Sovietski p.217', NULL),
  ('sovietski-fragmentation-grenade', 'Sovietski Fragmentation Grenade', 'rifts', 'weapon', NULL, NULL, NULL, '2D6 M.D. to a 5 foot (1.5 m) radius', 1, 'Thrown: 130 feet (39.6 m) for ordinary people, 200 feet (61 m) Light Machines, 300 feet (91.4 m) Heavy Machines, 400 feet (122 m) Superheavy Machines. As a rifle grenade: varies, typically 1,200 feet (366 m)', NULL, NULL, NULL, NULL, NULL, 'The Sovietski''s standard fragmentation grenade, issued both as a hand grenade and as a rifle grenade that does the same damage. The target area must be in sight; throwing or firing into smoke, fog, foliage, netting, illusion or a crowd of vehicles is a blind attack at -10 to strike. The book prints no price.', 'Rifts World Book 36: Sovietski p.217', NULL),
  ('sovietski-high-explosive-grenade', 'Sovietski High Explosive Grenade', 'rifts', 'weapon', NULL, NULL, NULL, '4D6 M.D. to a 4 foot (1.2 m) radius', 1, 'Thrown: 130 feet (39.6 m) for ordinary people, 200 feet (61 m) Light Machines, 300 feet (91.4 m) Heavy Machines, 400 feet (122 m) Superheavy Machines. As a rifle grenade: varies, typically 1,200 feet (366 m)', NULL, NULL, NULL, NULL, NULL, 'A Sovietski high explosive grenade, made as a hand grenade and as a rifle grenade of equal damage. The target area must be visible or the attack is blind, at -10 to strike. The book prints no price.', 'Rifts World Book 36: Sovietski p.217', NULL),
  ('sovietski-silver-fragmentation-light-grenade', 'Silver Fragmentation Light Grenade (S.D.C.)', 'rifts', 'weapon', NULL, NULL, NULL, '2D4x10 S.D.C. to a 10 foot (3 m) radius', 0, 'Thrown: 130 feet (39.6 m) for ordinary people, 200 feet (61 m) Light Machines, 300 feet (91.4 m) Heavy Machines, 400 feet (122 m) Superheavy Machines. As a rifle grenade: varies, typically 1,200 feet (366 m)', NULL, NULL, NULL, NULL, NULL, 'An S.D.C. fragmentation grenade whose burst throws silver-coated fragments and wood, for fighting werebeasts, vampires and many kinds of demon. Comes as a hand or rifle grenade and is part of the Groza II''s standard grenade load. The book prints no price.', 'Rifts World Book 36: Sovietski p.217', NULL),
  ('sovietski-silver-fragmentation-heavy-grenade', 'Silver Fragmentation Heavy Grenade', 'rifts', 'weapon', NULL, NULL, NULL, '2D6 M.D. to a 4 foot (1.2 m) radius', 1, 'Thrown: 130 feet (39.6 m) for ordinary people, 200 feet (61 m) Light Machines, 300 feet (91.4 m) Heavy Machines, 400 feet (122 m) Superheavy Machines. As a rifle grenade: varies, typically 1,200 feet (366 m)', NULL, NULL, NULL, NULL, NULL, 'The Mega-Damage version of the silver fragmentation grenade: its burst sprays silver-coated shot against werebeasts, vampires and many demons. Comes as a hand or rifle grenade and is part of the Groza II''s standard grenade load. The book prints no price.', 'Rifts World Book 36: Sovietski p.217', NULL),
  ('sovietski-parachute-flare', 'Sovietski Parachute Flare', 'rifts', 'gear', NULL, 10, '10 credits each', 'Not a weapon; shot into a person it does 5D6 S.D.C. each melee round for one minute (four rounds), with a 50% chance of setting combustibles alight', 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A signal flare in a disposable hand-held launch tube. Three seconds after launch it lights and floats slowly down, burning for 60 seconds and lighting an area about 150 feet (45.7 m) across. This printing gives 5D6 S.D.C. for a flare fired into a person; the parachute flare already held from Triax and the NGR gives 6D6, so this is its own row.', 'Rifts World Book 36: Sovietski p.218', NULL),
  ('sovietski-ballistic-knife-bayonet', 'Ballistic Knife Bayonet', 'rifts', 'weapon', 2, 9500, '9,500 credits, mostly for the Vibro-Blade; fair availability', '1D6 M.D. Vibro-Blade, in melee or fired', 1, '30 feet (9.1 m) when fired', 'One blade; it must be recovered, or another fitted, before firing again', 'Single shot only', NULL, NULL, NULL, 'A rifle-only attachment used in place of a Vibro-Bayonet. It slashes and stabs like any bayonet, and as a last resort can shoot its Vibro-Blade at a foe a short way off. Neither W.P. Knife nor W.P. Targeting adds anything with it.', 'Rifts World Book 36: Sovietski p.218', NULL),
  ('sovietski-custom-grip', 'Custom Grip', 'rifts', 'gear', NULL, 400, '400 credits; excellent availability', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A weapon grip molded to one soldier''s hand and the way he holds his gun, which steadies the weapon and makes it harder to drop. Anyone else using the weapon finds it awkward and is -1 to strike. Adds negligible weight.', 'Rifts World Book 36: Sovietski p.218', NULL),
  ('sovietski-weapon-flashlight', 'Weapon Flashlight', 'rifts', 'gear', NULL, 100, '100 credits; excellent availability', NULL, 0, 'Best illumination at 300 feet (91.4 m) or less', NULL, NULL, NULL, NULL, NULL, 'A flashlight clipped to the barrel of a gun, lighting what the weapon points at as an ordinary flashlight would. Adds negligible weight.', 'Rifts World Book 36: Sovietski p.218', NULL),
  ('sovietski-flash-suppressor', 'Sovietski Flash Suppressor', 'rifts', 'gear', 2, 350, '350 credits; excellent availability', NULL, 0, 'Cuts the weapon''s range by 20%; with a silencer as well, by 40% and -2 to strike', NULL, NULL, NULL, NULL, NULL, 'A muzzle attachment that hides the flash of a firing gun, at -1 to strike. It cannot be fitted to energy weapons, shotguns, rail guns or other heavy weapons. A generic attachment for any suitable gun, unlike the per-weapon-type suppressors held from Heroes Unlimited and Nightbane.', 'Rifts World Book 36: Sovietski p.218', NULL),
  ('sovietski-grenade-launcher', 'Under-Barrel Grenade Launcher', 'rifts', 'weapon', 5, 15000, '15,000 credits; not made for pistols or heavy weapons, otherwise good availability', 'As per the rifle grenade loaded', 1, 'Varies; typically 1,200 feet (366 m)', 'One round in the single-shot launcher, or 6 grenades in a small drum or magazine', 'One at a time', NULL, NULL, NULL, 'A grenade launcher mounted under a rifle barrel. It weighs 5 lbs (2.25 kg), or 7 lbs (3.1 kg) in the version with the six-grenade magazine.', 'Rifts World Book 36: Sovietski p.218', NULL),
  ('sovietski-optical-scopes', 'Optical Scopes', 'rifts', 'gear', NULL, NULL, 'Good availability; the book prints no price', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Gun sights of many kinds. Each one works roughly like the matching bionic eye implant: passive nightvision, infrared, laser targeting or telescopic vision.', 'Rifts World Book 36: Sovietski p.218', NULL),
  ('sovietski-silencer', 'Sovietski Silencer', 'rifts', 'gear', NULL, 500, '500 credits; fair availability', NULL, 0, 'Cuts the weapon''s range by 20%; with a flash suppressor as well, by 40% and -2 to strike', NULL, NULL, NULL, NULL, NULL, 'A muzzle attachment that quiets the shots of a revolver, pistol or rifle for covert work, at -1 to strike. It does not fit shotguns, rail guns, grenade launchers or other heavy weapons. A generic attachment, unlike the per-weapon-type silencers held from Heroes Unlimited and Nightbane.', 'Rifts World Book 36: Sovietski p.218', NULL),
  ('sovietski-vibro-bayonet', 'Sovietski Vibro-Bayonet', 'rifts', 'weapon', 1, 7500, '7,500 credits for either type of attachment', '1D4 M.D. on a pistol or submachine-gun; 1D6 M.D. on a rifle', 1, 'Within reach', NULL, NULL, NULL, NULL, NULL, 'A small Vibro-Blade fixed under the barrel of a rifle, pistol or submachine-gun for slashing and stabbing anyone who closes to melee range. The Vibro-Bayonet held from Rifts World Book 8: Japan does 1D6+1 M.D. at the same price; this printing gives different damage by mount, so it is its own row.', 'Rifts World Book 36: Sovietski p.218', NULL),
  ('ak-147-kalashnikov', 'AK-147 Kalashnikov (S.D.C.)', 'rifts', 'weapon', 7, 1100, '1,100 credits on the black market; excellent availability; free to Red Star Reservists', '5D6 S.D.C. per round; 1D4x10 S.D.C. per three-round burst; 1D6x10 S.D.C. per six-round burst', 0, '1,300 feet (396 m)', '20, 30 or 60 round magazines, or a 120 round drum that adds 10 lbs (4.5 kg)', 'Each single shot or burst counts as one attack', NULL, NULL, NULL, 'The commonest gun in the Sovietski, an AK-47 in all but materials: iron sights, a folding metal or fixed wooden stock, and a light M.D.C. body that keeps it light and very tough. Millions were recovered from pre-Rifts depots and caches once the Sovietski emerged. Called the weapon of the people.', 'Rifts World Book 36: Sovietski p.219', NULL),
  ('ak-247ll-light-laser-kalashnikov', 'AK-247LL Light Laser Kalashnikov', 'rifts', 'weapon', 9, 15000, '15,000 credits on the black market; excellent availability; free to Red Star Reservists', '1D6 M.D. per single blast; 3D6 M.D. per three-pulse blast', 1, '1,500 feet (457 m)', '30 single shots or 10 three-pulse bursts per E-Clip', 'Each single shot or burst counts as one attack', NULL, NULL, NULL, 'A light pulse laser built on the old Kalashnikov pattern, a military-grade weapon common with police, the Sovietski Army, the Red Star Reserves and country and wilderness folk. Fires single shots or three-pulse bursts; folding metal or fixed wooden stock. The Kalashnikov look was kept for energy weapons on purpose, for the confidence and pride a familiar design gives.', 'Rifts World Book 36: Sovietski p.219', NULL),
  ('ak-247hl-heavy-laser-kalashnikov', 'AK-247HL Heavy Laser Kalashnikov', 'rifts', 'weapon', 11.5, 23000, '23,000 credits on the black market; excellent availability; free to officers of the Red Star Reserves', '2D6 M.D. per single shot; 6D6 M.D. per three-pulse blast; can be set to 1D6x10 S.D.C.', 1, '2,000 feet (610 m)', '20 single shots or 6 three-pulse blasts per standard E-Clip', 'Each single shot or pulse counts as one attack', NULL, NULL, NULL, 'The heavy pulse laser Kalashnikov carried by Sovietski soldiers, firing single blasts or three-pulse bursts, with a folding metal or fixed wooden stock. The book prints its burst damage as 6D6 without a unit, under its Mega-Damage label.', 'Rifts World Book 36: Sovietski p.219', NULL),
  ('ak-347cr-cyborg-kalashnikov', 'AK-347CR Cyborg Kalashnikov', 'rifts', 'weapon', 150, 60000, '60,000 credits for the rail gun on the black market; fair availability; exclusive to the Sovietski Army', '1D6 M.D. per round; 1D6x10 M.D. per 20 round burst', 1, '4,000 feet (1,219 m)', 'Belt-fed: 800 round drum (40 bursts), 1,600 round drum (80 bursts) or 2,000 round drum (100 bursts)', 'Each single shot or burst counts as one attack', NULL, NULL, NULL, 'A big belt-fed rail gun styled after the AK-247, used by every class of Sovietski cyborg and liked best by Heavy and Superheavy Machines. Drums weigh 130 lbs (58.5 kg) for 800 rounds, 230 lbs (103 kg) for 1,600 and 286 lbs (129 kg) for 2,000. A Superheavy Machine may wear the 800 round drum at the hip or on the back; the larger two are carried or mounted on the back. Those big drums slow a Light Machine''s speed and leaps by 20% with a -15% penalty to Acrobatics, Climbing, Prowl, Swimming and similar skills; a Heavy Machine loses 10% speed and takes -5%.', 'Rifts World Book 36: Sovietski p.219-220', NULL),
  ('sovietski-dragunov-svd', 'Dragunov SVD Rifle (S.D.C.)', 'rifts', 'weapon', 9.5, 6000, '6,000 credits on the black market; poor availability', '7D6 S.D.C. per round', 0, '2,700 feet (823 m)', 'Eight round magazine', 'Single shots only; each counts as one melee attack', NULL, NULL, NULL, 'The pre-Rifts Dragunov sniper rifle as the Sovietski issues it to designated marksmen in its infantry, especially the Spetsnaz: sturdy, well made and accurate, for picking off key targets and breaking up enemy formations. Aimed and Called Shots get +1 to strike. Its figures differ from the Heroes Unlimited and Nightbane Dragunov rows, which are left as they are.', 'Rifts World Book 36: Sovietski p.220', NULL),
  ('dragunov-svd-l2a-laser-sniper-rifle', 'Dragunov SVD-L2A Laser Sniper Rifle', 'rifts', 'weapon', 9.7, 36000, '36,000 credits; poor to fair availability', '3D6 M.D. per single blast', 1, '4,000 feet (1,219 m)', '11 shots per standard E-Clip', 'Single shots only; each counts as one melee attack', NULL, NULL, NULL, 'A powerful long-range laser sniper rifle given to designated marksmen of the special forces and Spetsnaz, every bit as rugged as the S.D.C. Dragunov it is modeled on. Aimed and Called Shots get +1 to strike.', 'Rifts World Book 36: Sovietski p.220', NULL),
  ('svd-3b-super-dragunov', 'SVD-3B Super Dragunov Anti-Materiel Rifle', 'rifts', 'weapon', 198, 90000, 'Rare: 90,000+ credits if it ever reaches the black market; the Sovietski has shared it with no one', 'As per rifle grenade type: 2D6 M.D. to 5D6 M.D.; double damage on a Natural 20', 1, '2,500 feet (762 m)', 'Ten round magazine; each clip weighs 25 lbs (11 kg)', 'Single shots only; each counts as one melee attack', NULL, NULL, NULL, 'A huge single-shot rail gun shaped like an outsized Dragunov, 7 feet (2.1 m) long, whose bore takes rifle grenades fed from a magazine like a bolt-action rifle''s. Heavy and Superheavy Machines and trained Wolverine People handle it from any position; its weight, length and recoil put it nearly beyond unaugmented humans and Light Machines. About half carry a bipod and telescopic sight. Cyborg snipers use it on sensor and communications arrays, key personnel, weapon turrets, thrusters and tires, and for kill shots on demons and monsters. Aimed and Called Shots get +1 to strike; -3 on any other shot; -3 to strike for Light Machines and -6 for humans even when aiming. Rare even in the Sovietski military.', 'Rifts World Book 36: Sovietski p.220', NULL),
  ('ots-38-groza-ii-terror', 'OTs-38 Groza II "Terror II"', 'rifts', 'weapon', 8, 45000, '45,000 credits; fair availability, good to law enforcement agencies', 'Ion blaster 4D6 M.D. per single shot; grenades as per the rifle grenade loaded (standard load: Silver Fragmentation Light 2D4x10 S.D.C. in a 10 foot/3 m radius, Silver Fragmentation Heavy 2D6 M.D. in a 4 foot/1.2 m radius, Heavy Explosive 5D6 M.D. in a 4 foot/1.2 m radius, and Smoke)', 1, 'Ion: 500 feet (152 m); grenade launcher: 150 feet (45.7 m)', '40 shots from a G-Clip (long E-Clip); 20 from a standard E-Clip in an E-Clip Adapter; the grenade launcher is hand-loaded one round at a time', 'Each blast counts as one melee attack; the ion blaster and grenade launcher share a trigger and cannot fire together', NULL, NULL, NULL, 'A Spetsnaz favorite for enforcement and assault: a short bullpup ion rifle built to look like the pre-Rifts OTs-14 Groza, with a single-shot under-barrel grenade launcher picked by a three-position selector (rifle, launcher, safe). The short barrel suits alleys, houses, tunnels, caves and thick forest, and it works underwater and in freezing cold. It trades range and rate of fire for heavy damage and reliability. The G-Clip was introduced in Warlords of Russia (p.178). The standard load names a Heavy Explosive grenade at 5D6 M.D., which the grenade list on p.217 does not print.', 'Rifts World Book 36: Sovietski p.220-221', NULL),
  ('sh-31-ballistic-knife', 'SH-31 Ballistic Knife', 'rifts', 'weapon', 1, 7800, '7,800 credits on the black market, mostly for the Vibro-Blade; fair availability', '1D6 M.D. Vibro-Blade, in melee or fired (a normal ballistic knife does 1D6 S.D.C.)', 1, '20 feet (6.1 m) when fired', 'One blade; the handle is useless until the blade is recovered and reloaded or another is fitted', 'Single shot only', NULL, NULL, NULL, 'A spring- or gas-driven knife that can launch its blade, here a Vibro-Blade that holds its charge in flight; otherwise it fights as an ordinary knife. Spetsnaz troops and assassins like to circle a foe and shoot the blade before he sees it coming, and some carry two, with a third hidden in a cybernetic compartment. Neither W.P. Knife nor W.P. Targeting adds anything with it.', 'Rifts World Book 36: Sovietski p.221', NULL),
  ('s-30-89-bear-tooth-ion-pistol', 'S-30-89 "Bear Tooth" Ion Pistol', 'rifts', 'weapon', 10, 16000, '16,000 credits on the black market; 600 more to silver-plate the blade; poor availability', 'Ion blaster 4D6 M.D. per shot; Vibro-Blade 2D6 M.D.', 1, 'Vibro-Blade: melee. Ion blaster: 200 feet (61 m), meant for point-blank work', '12 ion blasts per standard E-Clip', 'Each slash, chop, stab or single shot counts as one melee attack', NULL, NULL, NULL, 'A heavy Vibro-Blade, broader than a bayonet or Vibro-Knife, joined to a short-ranged ion blaster, sized for Heavy and Superheavy Machines but also used by monster hunters, Wolverine People, Light Machines and a few Spetsnaz. It is known for the stab and blast: once the blade is in a cyborg or monster, the gun is fired as a second attack that the victim cannot parry or dodge. Backing away first costs him another 2D4 M.D. from the blade, and wrenching free 4D4 M.D., and he is still -4 to dodge and -4 on initiative against the shot. The blast knocks him off the blade but leaves him in range.', 'Rifts World Book 36: Sovietski p.221', NULL),
  ('s-30-51-cyborg-grenade-revolver', 'S-30-51 Cyborg Grenade Revolver', 'rifts', 'weapon', 15, 40000, '40,000 credits on the black market; poor availability', 'As per the grenade: Fragmentation 2D6 M.D. to a 6 foot (1.8 m) radius; High Explosive 3D6 M.D. to a 3 foot (0.9 m) radius; Plasma 5D6 M.D. to a 6 foot (1.8 m) radius; or Smoke, Stun/Flash or Tear Gas', 1, '300 feet (91.4 m)', 'Twelve rounds; reloaded in two melee actions with its speed-loader, or by hand in one full melee round', 'One or two shots at a time', NULL, NULL, NULL, 'An experimental oversized sidearm for Light, Heavy and Superheavy Machines, like a revolver three times normal size with two barrels stacked one over the other. Each turn of the cylinder lines up two rifle grenades so it can fire one or both. Hand-loaded one grenade per melee action. 15 lbs (6.75 kg) empty, 18 lbs (8.1 kg) loaded. The grenade figures printed here differ from the p.217 grenade list.', 'Rifts World Book 36: Sovietski p.221-222', NULL),
  ('sh-37-cyborg-vibro-sword-shotgun', 'SH-37 Cyborg Vibro-Sword Shotgun "Silver Viper"', 'rifts', 'weapon', 19, 15000, '15,000 credits on the black market; poor availability', 'Silver Vibro-Blade 2D6 M.D.; shotgun as per the load, usually an S.D.C. round that harms werewolves, vampires and demons (see the special ammunition rows)', 1, 'Melee, or 120 feet (36.6 m) for the shotgun', 'Eight shotgun rounds', 'Single shots only; each counts as one melee attack', NULL, NULL, NULL, 'A cutlass-shaped Vibro-Sword built round a short shotgun, 3 feet 5 inches (1 m) long. Wolverine People, who love it, and Light and Heavy Machines swing it one-handed with ease; humans are -2 to strike and parry with the blade and -2 to strike with the gun even two-handed. The blade is silver-coated and the gun takes solid or plated silver slugs, silver scatter loads, wood rounds or plain shells, which makes it a favorite against monsters and the supernatural.', 'Rifts World Book 36: Sovietski p.222', NULL),
  ('s-10-68-harpoon-laser-pistol', 'S-10-68 Harpoon Laser Pistol', 'rifts', 'weapon', 6.5, 14000, '14,000 credits on the black market; poor availability', 'Laser 2D6 M.D. per shot; harpoon 1D4 M.D. Vibro-Blade tip', 1, 'Harpoon 200 feet (61 m); laser 800 feet (244 m) on land, 1,200 feet (366 m) underwater', 'Laser 20 blasts per standard E-Clip; one short harpoon, hand-loaded, with 6 more in a pouch', 'Each blast or harpoon shot counts as one melee attack', NULL, NULL, NULL, 'A sidearm for Sovietski scuba divers and cyborgs in underwater work and ship boarding: a long blue-green laser with a small modular harpoon launcher underneath. The harpoon serves for silent kills, fishing and warning shots, or trails a separate cable to rig zip-lines and boarding lines, anchored to the boarders'' own ship.', 'Rifts World Book 36: Sovietski p.222', NULL),
  ('sh-21-vibro-sickle', 'SH-21 Vibro-Sickle', 'rifts', 'weapon', 4, 8000, 'Human-sized 8,000 credits; giant-sized 16,000 credits; fair availability', 'Human-sized 2D4 M.D.; giant-sized 3D6 M.D.', 1, 'Melee', NULL, NULL, NULL, NULL, NULL, 'A large curved Vibro-Blade hand weapon, good for slashing, chopping and parrying, carried over from the pre-Cataclysm Soviet arsenal. Common with Sovietski Light and Heavy Machines and standard issue to the Thunderhammer cyborg. The human-sized sickle weighs 4 lbs (1.8 kg), the giant-sized one 20 lbs (9 kg).', 'Rifts World Book 36: Sovietski p.222', NULL),
  ('sh-76-chainsaw-glaive', 'SH-76 Chainsaw Glaive', 'rifts', 'weapon', 40, 13000, '13,000 credits on the black market; fair to poor availability', 'Chainsaw 4D6+4 M.D.; the butt does P.S. punch damage', 1, 'Melee; reach varies with the user''s size', '30 minutes per standard E-Clip', NULL, NULL, NULL, NULL, 'A cyborg pole arm, the Sovietski''s answer to a Romanov camp design: a long shaft with a textured middle grip, a rounded metal butt for blunt blows and a reinforced chainsaw head that cuts through foes, debris, light fortifications and sensor or communications arrays. It comes 9 feet (2.7 m) long for Light and Heavy Machines, at 40 lbs (18 kg), and 14 feet (4.3 m) for Superheavy Machines, at 60 lbs (27 kg), doing the same damage. Its stat block sits beside its drawing on p.223.', 'Rifts World Book 36: Sovietski p.222-223', NULL),
  ('sh-79-vibro-scythe', 'SH-79 Vibro-Scythe', 'rifts', 'weapon', 70, 17000, '17,000 or 30,000 credits, two prices for its two sizes; fair availability', 'Human-sized, or for Light and Heavy Machines, 3D6 M.D.; giant-sized for Superheavy Machines 4D6 M.D.', 1, 'Hand to hand only', NULL, NULL, NULL, NULL, NULL, 'A cyborg pole arm: a heavy scythe with a silver-plated, curved Vibro-Blade 5 feet (1.5 m) long. Simple, but its weight makes every blow punishing. Mostly carried by Heavy and Superheavy Machines and now and then a Light Machine; many were sold to the Romanov camp, whose Avenging Angel Shocktroopers use it widely. The book does not say which of its two prices goes with which size.', 'Rifts World Book 36: Sovietski p.223', NULL);

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 34 gear rows are in' AS assertion, count(*) AS got, 34 AS want
